/// One factor-conditioned local edge in the source-neutral exterior boundary chart.  `source`
/// and `target` are universal boundary-port coordinates: opening is zero, an octet `b` is
/// `b + 1`, and closure is 257.  The population is a condensed developmental current.  No path,
/// surface variant, clause, word, source occurrence, or inverse source address survives here.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct SourceNeutralExteriorRealizationTransition {
    /// Stable anonymous relational-face class which carried this local boundary incidence.
    pub face: u32,
    pub source: u16,
    pub target: u16,
    pub occurrence_population: u64,
}

// Eight million local incidences are legitimate standing on the current corpus.  Their named
// Rust fields are an apparatus convenience, not eight million repetitions of a wire ontology;
// serialize each occurrence as the exact ordered carrier `[site, source, target, population]`.
impl Serialize for SourceNeutralExteriorRealizationTransition {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        (
            self.face,
            self.source,
            self.target,
            self.occurrence_population,
        )
            .serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for SourceNeutralExteriorRealizationTransition {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let (face, source, target, occurrence_population) =
            <(u32, u16, u16, u64)>::deserialize(deserializer)?;
        Ok(Self {
            face,
            source,
            target,
            occurrence_population,
        })
    }
}

