/// Coarsest exact suffix quotient of the rested realization sites.  Two sites meet only when
/// their contemporary face class, incidence multiplicity, and complete successor suffix agree.
/// Because every local port transition is owned by the face and the sole spatial transition is
/// owned by `successor_site`, this structural quotient commutes with every admitted exterior
/// generator.  `site_to_class` is the complete reconstruction fibre; representatives are an
/// execution chart and never source identities.
#[derive(Debug, PartialEq, Eq)]
pub(crate) struct SourceNeutralExteriorSiteHistoryQuotient {
    site_to_class: Vec<u32>,
    representatives: Vec<u32>,
    fibres: Vec<Vec<u32>>,
    carrier_addresses: BTreeMap<(u32, u32, u8), u32>,
    carrier_representatives: Vec<(u32, u32, u8)>,
    carrier_fibres: Vec<Vec<(u32, u32, u8)>>,
    identity_sha256: String,
}

impl SourceNeutralExteriorSiteHistoryQuotient {
    fn found(
        morphology: &SourceNeutralExteriorRealizationMorphology,
        relational: &SourceNeutralRelationalMorphology,
    ) -> Result<Self, SourceNeutralRelationalError> {
        if morphology.sites.is_empty() || relational.cells.is_empty() {
            return Err(SourceNeutralRelationalError::Quotient);
        }
        let mut site_to_class = vec![None::<u32>; morphology.sites.len()];
        let mut signatures = BTreeMap::<(u32, u64, Option<u32>), u32>::new();
        let mut representatives = Vec::<u32>::new();
        let mut unresolved = morphology.sites.len();
        while unresolved != 0 {
            let before = unresolved;
            for (site_at, site) in morphology.sites.iter().enumerate() {
                if site_to_class[site_at].is_some() {
                    continue;
                }
                let successor_class = match site.successor_site {
                    Some(successor) => {
                        match site_to_class.get(successor as usize).copied().flatten() {
                            Some(class) => Some(class),
                            None => continue,
                        }
                    }
                    None => None,
                };
                let signature = (site.face, site.incidence_population, successor_class);
                let class = if let Some(class) = signatures.get(&signature).copied() {
                    class
                } else {
                    let class = u32::try_from(representatives.len())
                        .map_err(|_| SourceNeutralRelationalError::Extent)?;
                    signatures.insert(signature, class);
                    representatives.push(
                        u32::try_from(site_at).map_err(|_| SourceNeutralRelationalError::Extent)?,
                    );
                    class
                };
                site_to_class[site_at] = Some(class);
                unresolved -= 1;
            }
            if unresolved == before {
                return Err(SourceNeutralRelationalError::Quotient);
            }
        }
        let site_to_class = site_to_class
            .into_iter()
            .collect::<Option<Vec<_>>>()
            .ok_or(SourceNeutralRelationalError::Quotient)?;
        let mut fibres = vec![Vec::<u32>::new(); representatives.len()];
        for (site, class) in site_to_class.iter().copied().enumerate() {
            fibres[class as usize]
                .push(u32::try_from(site).map_err(|_| SourceNeutralRelationalError::Extent)?);
        }
        if fibres.iter().any(Vec::is_empty) {
            return Err(SourceNeutralRelationalError::Quotient);
        }
        // Lift the spatial suffix quotient to the complete pre-locking carrier.  Factor and phase
        // names do not survive when their separator weight and complete successor carrier agree;
        // this is the exact weighted future-consequence quotient missing from the raw all-port
        // expansion.
        let mut carrier_addresses = BTreeMap::<(u32, u32, u8), u32>::new();
        let mut carrier_signatures = BTreeMap::<(u32, Option<(u32, BigUint)>), u32>::new();
        let mut carrier_representatives = Vec::<(u32, u32, u8)>::new();
        let mut carrier_fibres = Vec::<Vec<(u32, u32, u8)>>::new();
        for site_class in 0..representatives.len() {
            let representative_site = morphology.site(representatives[site_class])?;
            let mut factor_phases = BTreeSet::<(u32, u8)>::new();
            for site in &fibres[site_class] {
                let occurrence = morphology.site(*site)?;
                let cell = relational
                    .cells
                    .get(occurrence.cell as usize)
                    .ok_or(SourceNeutralRelationalError::Quotient)?;
                factor_phases.extend(
                    cell.phase_population
                        .iter()
                        .map(|population| (population.factor, population.phase)),
                );
            }
            for (factor, phase) in factor_phases {
                let successor = match representative_site.successor_site {
                    Some(successor_site) => {
                        let successor = morphology.site(successor_site)?;
                        let successor_site_class = site_to_class[successor_site as usize];
                        let successor_carrier = carrier_addresses
                            .get(&(successor_site_class, factor, phase))
                            .copied()
                            .ok_or(SourceNeutralRelationalError::Quotient)?;
                        let population = phase_population(
                            &relational.faces[successor.face as usize].phase_population,
                            factor,
                            phase,
                        )
                        .ok_or(SourceNeutralRelationalError::Quotient)?;
                        Some((
                            successor_carrier,
                            BigUint::from(successor.incidence_population)
                                * BigUint::from(population),
                        ))
                    }
                    None => None,
                };
                let signature = (representative_site.face, successor);
                let carrier = if let Some(carrier) = carrier_signatures.get(&signature).copied() {
                    carrier
                } else {
                    let carrier = u32::try_from(carrier_representatives.len())
                        .map_err(|_| SourceNeutralRelationalError::Extent)?;
                    carrier_signatures.insert(signature, carrier);
                    carrier_representatives.push((site_class as u32, factor, phase));
                    carrier_fibres.push(Vec::new());
                    carrier
                };
                carrier_addresses.insert((site_class as u32, factor, phase), carrier);
                carrier_fibres[carrier as usize].push((site_class as u32, factor, phase));
            }
        }
        if carrier_representatives.is_empty()
            || carrier_fibres.iter().any(Vec::is_empty)
            || carrier_addresses.len() != carrier_fibres.iter().map(Vec::len).sum::<usize>()
        {
            return Err(SourceNeutralRelationalError::Quotient);
        }
        let presented_carrier_addresses = carrier_addresses
            .iter()
            .map(|(address, class)| (*address, *class))
            .collect::<Vec<_>>();
        let identity_sha256 = digest(&(
            "soma-life.source-neutral-exterior-site-history-quotient.v1",
            morphology.identity_sha256.as_str(),
            relational.identity_sha256.as_str(),
            &site_to_class,
            &representatives,
            &fibres,
            &presented_carrier_addresses,
            &carrier_representatives,
            &carrier_fibres,
        ));
        Ok(Self {
            site_to_class,
            representatives,
            fibres,
            carrier_addresses,
            carrier_representatives,
            carrier_fibres,
            identity_sha256,
        })
    }

    fn class(&self, site: u32) -> Result<u32, SourceNeutralRelationalError> {
        self.site_to_class
            .get(site as usize)
            .copied()
            .ok_or(SourceNeutralRelationalError::Quotient)
    }

    fn representative(&self, class: u32) -> Result<u32, SourceNeutralRelationalError> {
        self.representatives
            .get(class as usize)
            .copied()
            .ok_or(SourceNeutralRelationalError::Quotient)
    }

    fn carrier(
        &self,
        site_class: u32,
        factor: u32,
        phase: u8,
    ) -> Result<u32, SourceNeutralRelationalError> {
        self.carrier_addresses
            .get(&(site_class, factor, phase))
            .copied()
            .ok_or(SourceNeutralRelationalError::Quotient)
    }

    fn carrier_representative(
        &self,
        carrier: u32,
    ) -> Result<(u32, u32, u8), SourceNeutralRelationalError> {
        self.carrier_representatives
            .get(carrier as usize)
            .copied()
            .ok_or(SourceNeutralRelationalError::Quotient)
    }

    pub(super) fn source_population(&self) -> usize {
        self.site_to_class.len()
    }

    pub(super) fn quotient_population(&self) -> usize {
        self.carrier_representatives.len()
    }

    pub(super) fn reconstruction_population(&self) -> usize {
        self.carrier_fibres.iter().map(Vec::len).sum()
    }

    pub(super) fn identity(&self) -> &str {
        &self.identity_sha256
    }
}

