/// Exact native-section-to-exterior realization passage.
///
/// The entering phase is a separately caused projective current on `[0,1)`.  It meets the
/// complete target-current partition and returns the unique local phase inside the selected
/// half-open interval.  The returned factor section is the restriction of the entering section
/// through that selected incidence.  It therefore carries the entire realized prefix without a
/// caller-chosen history width, string, token, or private semantic echo.  No local maximum is
/// treated as an answer.  Both complete current sections, the interval, and the native lineage
/// remain beside the selected face as its reconstruction fibre.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct SourceNeutralExteriorRealizationPassage {
    pub schema: String,
    pub morphology_identity_sha256: String,
    pub native_section_identity_sha256: String,
    pub native_current_passage_identity_sha256: String,
    pub source_port: u16,
    pub factor_current: Vec<SourceNeutralExteriorRealizationFactorCurrent>,
    pub oriented_factor_current: Vec<SourceNeutralExteriorRealizationOrientedFactorCurrent>,
    pub native_oriented_faces: Vec<SourceNeutralNativeOrientedFace>,
    pub site_current: Vec<SourceNeutralExteriorRealizationSiteCurrent>,
    pub complex_site_current: Vec<SourceNeutralExteriorRealizationComplexSiteCurrent>,
    pub target_current: Vec<SourceNeutralExteriorRealizationTargetCurrent>,
    pub total_target_current: SourceNeutralPositiveCurrent,
    pub entering_realization_current_identity_sha256: String,
    pub entering_phase_numerator: BigUint,
    pub entering_phase_denominator: BigUint,
    pub selected_target_port: u16,
    pub selected_interval_begin: SourceNeutralPositiveCurrent,
    pub selected_interval_end: SourceNeutralPositiveCurrent,
    /// Current returned after the selected local boundary incidence acts.  This projective
    /// section is the unbounded causal memory of the emitted prefix; no caller chooses an n-gram
    /// order or context width.
    pub returned_factor_current: Vec<SourceNeutralExteriorRealizationFactorCurrent>,
    pub returned_site_current: Vec<SourceNeutralExteriorRealizationSiteCurrent>,
    pub returned_complex_site_current: Vec<SourceNeutralExteriorRealizationComplexSiteCurrent>,
    pub returned_phase_numerator: BigUint,
    pub returned_phase_denominator: BigUint,
    pub returned_realization_current_identity_sha256: String,
    pub source_boundary_total: bool,
    pub target_boundary_total: bool,
    pub complete_reconstruction_fibre_retained: bool,
    pub source_codec_consulted: bool,
    pub source_surface_reachable: bool,
    pub identity_sha256: String,
}

impl SourceNeutralExteriorRealizationPassage {
    pub(crate) fn validate(&self) -> Result<(), SourceNeutralRelationalError> {
        let source_complex_shadow = positive_site_shadow(&self.complex_site_current)?;
        let returned_complex_shadow = positive_site_shadow(&self.returned_complex_site_current)?;
        let site_total = self
            .site_current
            .iter()
            .fold(Ratio::zero(), |sum, site| sum + &site.current);
        let target_total = self
            .target_current
            .iter()
            .fold(Ratio::zero(), |sum, target| sum + &target.current);
        let returned_site_total = self
            .returned_site_current
            .iter()
            .fold(Ratio::zero(), |sum, site| sum + &site.current);
        let returned_factor_projection = self.returned_site_current.iter().fold(
            BTreeMap::<u32, SourceNeutralPositiveCurrent>::new(),
            |mut projection, current| {
                *projection.entry(current.factor).or_default() += &current.current;
                projection
            },
        );
        let returned_factor_projection = returned_factor_projection
            .into_iter()
            .map(
                |(factor, current)| SourceNeutralExteriorRealizationFactorCurrent {
                    factor,
                    current,
                },
            )
            .collect::<Vec<_>>();
        let entering_phase = Ratio::new(
            self.entering_phase_numerator.clone(),
            self.entering_phase_denominator.clone(),
        );
        let phase_position = &entering_phase * &self.total_target_current;
        let selected_interval = self
            .target_current
            .iter()
            .try_fold((Ratio::zero(), None), |(begin, selected), target| {
                let end = &begin + &target.current;
                Ok::<_, SourceNeutralRelationalError>(
                    if target.target_port == self.selected_target_port {
                        (end.clone(), Some((begin, end)))
                    } else {
                        (end, selected)
                    },
                )
            })?
            .1;
        if self.schema != SOURCE_NEUTRAL_EXTERIOR_REALIZATION_PASSAGE_SCHEMA
            || !is_digest(&self.morphology_identity_sha256)
            || !is_digest(&self.native_section_identity_sha256)
            || !is_digest(&self.native_current_passage_identity_sha256)
            || !is_digest(&self.entering_realization_current_identity_sha256)
            || !is_digest(&self.returned_realization_current_identity_sha256)
            || self.source_port >= 257
            || self.factor_current.is_empty()
            || self
                .factor_current
                .windows(2)
                .any(|pair| pair[0].factor >= pair[1].factor)
            || self
                .factor_current
                .iter()
                .any(|factor| factor.current.is_zero())
            || self.oriented_factor_current.is_empty()
            || self
                .oriented_factor_current
                .windows(2)
                .any(|pair| pair[0].factor >= pair[1].factor)
            || self
                .oriented_factor_current
                .iter()
                .any(|factor| factor.current.is_zero())
            || self.native_oriented_faces.is_empty()
            || self
                .native_oriented_faces
                .windows(2)
                .any(|pair| pair[0].mode >= pair[1].mode)
            || self.native_oriented_faces.iter().any(|face| {
                face.target_states.is_empty()
                    || face.target_states.windows(2).any(|pair| pair[0] >= pair[1])
            })
            || self.site_current.is_empty()
            || self.site_current.windows(2).any(|pair| {
                (
                    pair[0].carrier,
                    pair[0].factor,
                    pair[0].phase,
                    pair[0].local_source_port,
                ) >= (
                    pair[1].carrier,
                    pair[1].factor,
                    pair[1].phase,
                    pair[1].local_source_port,
                )
            })
            || self.site_current.iter().any(|site| {
                site.phase > 2 || site.local_source_port >= 257 || site.current.is_zero()
            })
            || self.site_current != source_complex_shadow
            || self.complex_site_current.is_empty()
            || self.complex_site_current.windows(2).any(|pair| {
                (
                    pair[0].carrier,
                    pair[0].factor,
                    pair[0].phase,
                    pair[0].local_source_port,
                ) >= (
                    pair[1].carrier,
                    pair[1].factor,
                    pair[1].phase,
                    pair[1].local_source_port,
                )
            })
            || self.complex_site_current.iter().any(|site| {
                site.phase > 2
                    || site.local_source_port >= 257
                    || site.incidence_coefficient.is_zero()
            })
            || self.target_current.is_empty()
            || self
                .target_current
                .windows(2)
                .any(|pair| pair[0].target_port >= pair[1].target_port)
            || self.target_current.iter().any(|target| {
                target.target_port == 0
                    || target.target_port > 257
                    || target.current.is_zero()
                    || target.supporting_transition_population == 0
            })
            || site_total != Ratio::one()
            || target_total != self.total_target_current
            || self.total_target_current != Ratio::one()
            || self.total_target_current.is_zero()
            || self.entering_phase_denominator.is_zero()
            || self.entering_phase_numerator >= self.entering_phase_denominator
            || self.selected_target_port == 0
            || self.selected_target_port > 257
            || selected_interval.as_ref().is_none_or(|(begin, end)| {
                begin != &self.selected_interval_begin || end != &self.selected_interval_end
            })
            || phase_position < self.selected_interval_begin
            || phase_position >= self.selected_interval_end
            || self
                .target_current
                .iter()
                .find(|target| target.target_port == self.selected_target_port)
                .is_none_or(|target| {
                    &self.selected_interval_end - &self.selected_interval_begin != target.current
                })
            || self.returned_factor_current.is_empty()
            || self
                .returned_factor_current
                .windows(2)
                .any(|pair| pair[0].factor >= pair[1].factor)
            || self
                .returned_factor_current
                .iter()
                .any(|factor| factor.current.is_zero())
            || self.returned_site_current.is_empty()
            || self.returned_site_current.windows(2).any(|pair| {
                (
                    pair[0].carrier,
                    pair[0].factor,
                    pair[0].phase,
                    pair[0].local_source_port,
                ) >= (
                    pair[1].carrier,
                    pair[1].factor,
                    pair[1].phase,
                    pair[1].local_source_port,
                )
            })
            || self.returned_site_current.iter().any(|site| {
                site.phase > 2 || site.local_source_port > 257 || site.current.is_zero()
            })
            || self.returned_factor_current != returned_factor_projection
            || returned_site_total != Ratio::one()
            || self.returned_site_current != returned_complex_shadow
            || self.returned_complex_site_current.is_empty()
            || self.returned_complex_site_current.windows(2).any(|pair| {
                (
                    pair[0].carrier,
                    pair[0].factor,
                    pair[0].phase,
                    pair[0].local_source_port,
                ) >= (
                    pair[1].carrier,
                    pair[1].factor,
                    pair[1].phase,
                    pair[1].local_source_port,
                )
            })
            || self.returned_complex_site_current.iter().any(|site| {
                site.phase > 2
                    || site.local_source_port > 257
                    || site.incidence_coefficient.is_zero()
            })
            || self.returned_phase_denominator.is_zero()
            || self.returned_phase_numerator >= self.returned_phase_denominator
            || !self.source_boundary_total
            || !self.target_boundary_total
            || !self.complete_reconstruction_fibre_retained
            || self.source_codec_consulted
            || self.source_surface_reachable
            || self.identity_sha256 != self.rederived_identity()
        {
            return Err(SourceNeutralRelationalError::Quotient);
        }
        Ok(())
    }

    pub(crate) fn rederived_identity(&self) -> String {
        digest(&(
            (
                self.schema.as_str(),
                self.morphology_identity_sha256.as_str(),
                self.native_section_identity_sha256.as_str(),
                self.native_current_passage_identity_sha256.as_str(),
                self.source_port,
            ),
            (
                &self.factor_current,
                &self.oriented_factor_current,
                &self.native_oriented_faces,
                &self.site_current,
                &self.complex_site_current,
                &self.target_current,
                &self.total_target_current,
                self.entering_realization_current_identity_sha256.as_str(),
                &self.entering_phase_numerator,
                &self.entering_phase_denominator,
            ),
            (
                self.selected_target_port,
                &self.selected_interval_begin,
                &self.selected_interval_end,
                &self.returned_factor_current,
                &self.returned_site_current,
                &self.returned_complex_site_current,
                &self.returned_phase_numerator,
                &self.returned_phase_denominator,
                self.returned_realization_current_identity_sha256.as_str(),
            ),
            (
                self.source_boundary_total,
                self.target_boundary_total,
                self.complete_reconstruction_fibre_retained,
                self.source_codec_consulted,
                self.source_surface_reachable,
            ),
        ))
    }
}

fn gcd_biguint(mut left: BigUint, mut right: BigUint) -> BigUint {
    while !right.is_zero() {
        let remainder = &left % &right;
        left = right;
        right = remainder;
    }
    left
}

fn positive_complex_norm(
    current: &ExactComplexWaveCurrent,
) -> Result<SourceNeutralPositiveCurrent, SourceNeutralRelationalError> {
    let norm = current.norm_square();
    if norm.is_negative() || norm.denom().is_zero() {
        return Err(SourceNeutralRelationalError::Quotient);
    }
    Ok(Ratio::new(
        norm.numer().magnitude().clone(),
        norm.denom().magnitude().clone(),
    ))
}

fn positive_site_shadow(
    complex: &[SourceNeutralExteriorRealizationComplexSiteCurrent],
) -> Result<Vec<SourceNeutralExteriorRealizationSiteCurrent>, SourceNeutralRelationalError> {
    if complex.is_empty()
        || complex.windows(2).any(|pair| {
            (
                pair[0].carrier,
                pair[0].factor,
                pair[0].phase,
                pair[0].local_source_port,
            ) >= (
                pair[1].carrier,
                pair[1].factor,
                pair[1].phase,
                pair[1].local_source_port,
            )
        })
        || complex
            .iter()
            .any(|current| current.incidence_coefficient.is_zero())
    {
        return Err(SourceNeutralRelationalError::Quotient);
    }
    let total = complex.iter().fold(Ratio::zero(), |sum, current| {
        sum + &current.incidence_coefficient
    });
    if total.is_zero() {
        return Err(SourceNeutralRelationalError::Quotient);
    }
    // This is the conserved incidence-mass receiver of an already sorted unique dependent
    // section.  No second junction is needed: rebuilding the same keys through a map formerly
    // turned this linear projection into a costly rescan at every exterior order.
    Ok(complex
        .iter()
        .map(|current| SourceNeutralExteriorRealizationSiteCurrent {
            carrier: current.carrier,
            site: current.site,
            factor: current.factor,
            phase: current.phase,
            local_source_port: current.local_source_port,
            current: &current.incidence_coefficient / &total,
        })
        .collect())
}

fn reduce_fraction(
    numerator: &mut BigUint,
    denominator: &mut BigUint,
) -> Result<(), SourceNeutralRelationalError> {
    if denominator.is_zero() || *numerator >= *denominator {
        return Err(SourceNeutralRelationalError::Quotient);
    }
    let divisor = gcd_biguint(numerator.clone(), denominator.clone());
    if divisor.is_zero() {
        return Err(SourceNeutralRelationalError::Quotient);
    }
    *numerator /= &divisor;
    *denominator /= divisor;
    Ok(())
}

use holonic_engine::is_sha256_digest as is_digest;

fn phase_population(
    populations: &[SourceNeutralPhasePopulation],
    factor: u32,
    phase: u8,
) -> Option<u64> {
    populations
        .binary_search_by_key(&(factor, phase), |population| {
            (population.factor, population.phase)
        })
        .ok()
        .map(|at| populations[at].occurrence_population)
}

pub(super) fn invalid_support(support: &[u32], factor_population: u32) -> bool {
    support.is_empty()
        || support.windows(2).any(|pair| pair[0] >= pair[1])
        || support.iter().any(|factor| *factor >= factor_population)
}

pub(super) fn realization_sites_match_relational(
    sites: &[SourceNeutralExteriorRealizationSite],
    relational: &SourceNeutralRelationalMorphology,
) -> Result<bool, SourceNeutralRelationalError> {
    let expected_population = relational
        .cells
        .iter()
        .try_fold(0_usize, |sum, cell| {
            sum.checked_add(cell.oriented_boundary.len())
        })
        .ok_or(SourceNeutralRelationalError::Extent)?;
    if sites.len() != expected_population {
        return Ok(false);
    }
    for site in sites {
        let Some(cell) = relational.cells.get(site.cell as usize) else {
            return Ok(false);
        };
        let positions = relational_boundary_positions(cell.oriented_boundary.len())?;
        let Some(at) = positions
            .iter()
            .position(|position| *position == site.boundary_position)
        else {
            return Ok(false);
        };
        if cell.oriented_boundary.get(at).copied() != Some(site.face) {
            return Ok(false);
        }
        let Some(face) = relational.faces.get(site.face as usize) else {
            return Ok(false);
        };
        if !face.cell_incidence.iter().any(|incidence| {
            incidence.cell == site.cell
                && incidence.boundary_position == site.boundary_position
                && incidence.incidence_population == site.incidence_population
        }) {
            return Ok(false);
        }
        match (positions.get(at + 1), site.successor_site) {
            (None, None) => {}
            (Some(next_position), Some(successor_at)) => {
                let Some(successor) = sites.get(successor_at as usize) else {
                    return Ok(false);
                };
                if successor.cell != site.cell
                    || successor.boundary_position != *next_position
                    || cell.oriented_boundary.get(at + 1).copied() != Some(successor.face)
                {
                    return Ok(false);
                }
            }
            _ => return Ok(false),
        }
    }
    Ok(true)
}

pub(super) fn relational_boundary_positions(
    boundary_extent: usize,
) -> Result<&'static [u8], SourceNeutralRelationalError> {
    match boundary_extent {
        3 => Ok(&[0, 1, 3]),
        4 => Ok(&[0, 1, 2, 3]),
        _ => Err(SourceNeutralRelationalError::Quotient),
    }
}

pub(super) fn key(value: &impl Serialize) -> Result<Vec<u8>, SourceNeutralRelationalError> {
    serde_json::to_vec(value).map_err(|_| SourceNeutralRelationalError::Extent)
}

pub(super) fn partition(keys: Vec<Vec<u8>>) -> Result<Vec<u32>, SourceNeutralRelationalError> {
    if keys.is_empty() {
        return Err(SourceNeutralRelationalError::Developmental);
    }
    let mut order = (0..keys.len()).collect::<Vec<_>>();
    order.sort_unstable_by(|left, right| keys[*left].cmp(&keys[*right]));
    let mut classes = vec![0_u32; keys.len()];
    let mut class = 0_u32;
    for (at, item) in order.iter().copied().enumerate() {
        if at != 0 && keys[item] != keys[order[at - 1]] {
            class = class
                .checked_add(1)
                .ok_or(SourceNeutralRelationalError::Extent)?;
        }
        classes[item] = class;
    }
    Ok(classes)
}

pub(super) fn canonicalize_partition(
    classes: Vec<u32>,
) -> Result<Vec<u32>, SourceNeutralRelationalError> {
    partition(classes.iter().map(key).collect::<Result<Vec<_>, _>>()?)
}

pub(super) fn same_partition(left: &[u32], right: &[u32]) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut mapping = std::collections::BTreeMap::<u32, u32>::new();
    let mut reverse = std::collections::BTreeMap::<u32, u32>::new();
    left.iter()
        .copied()
        .zip(right.iter().copied())
        .all(|(l, r)| {
            mapping.get(&l).is_none_or(|seen| *seen == r)
                && reverse.get(&r).is_none_or(|seen| *seen == l)
                && {
                    mapping.insert(l, r);
                    reverse.insert(r, l);
                    true
                }
        })
}

pub(super) fn face_address(class: u32, face: &SourceNeutralRelationalFace) -> String {
    digest(&(
        "soma-life.source-neutral-relational-face.v1",
        class,
        &face.factor_support,
        &face.phase_population,
        &face.cell_incidence,
    ))
}

pub(super) fn cell_address(class: u32, cell: &SourceNeutralRelationalCell) -> String {
    digest(&(
        "soma-life.source-neutral-relational-cell.v1",
        class,
        &cell.oriented_boundary,
        &cell.factor_support,
        &cell.phase_population,
    ))
}

fn digest(value: &impl Serialize) -> String {
    let bytes = serde_json::to_vec(value).expect("source-neutral relational identity serializes");
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}
